from .ranges import bounds


def serve(data, range_header=None):
    if range_header is None:
        return 200, {'Content-Length': str(len(data))}, data

    span = bounds(range_header, len(data))
    if span is None:
        return (
            416,
            {'Content-Length': '0', 'Content-Range': f'bytes */{len(data)}'},
            b'',
        )

    start, end = span
    body = data[start:end + 1]
    return (
        206,
        {
            'Content-Length': str(len(body)),
            'Content-Range': f'bytes {start}-{end}/{len(data)}',
        },
        body,
    )
